CREATE EXTENSION IF NOT EXISTS postgis;

CREATE TABLE IF NOT EXISTS nav_nodes (node_id BIGINT PRIMARY KEY, node_type TEXT, confidence REAL, geom geometry(Point, 4326));
CREATE TABLE IF NOT EXISTS nav_edges (edge_id BIGINT PRIMARY KEY, source BIGINT REFERENCES nav_nodes(node_id), target BIGINT REFERENCES nav_nodes(node_id), length_m REAL, walkable BOOLEAN, confidence REAL, geom geometry(LineString, 4326));
CREATE INDEX IF NOT EXISTS nav_nodes_geom_idx ON nav_nodes USING GIST (geom);
CREATE INDEX IF NOT EXISTS nav_edges_geom_idx ON nav_edges USING GIST (geom);

